gCX(){return"\u0417\u0430\u0432\u0435\u0440\u0448\u0456\u0442\u044c \u0430\u0431\u043e \u0440\u043e\u0437\u0456\u0440\u0432\u0456\u0442\u044c \u043f\u043e\u0442\u043e\u0447\u043d\u0456 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gD_(){return"\u041f\u043e\u043f\u0440\u043e\u0441\u0456\u0442\u044c \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a\u0430 \u0437\u0430\u0432\u0435\u0440\u0448\u0438\u0442\u0438 \u0430\u0431\u043e \u0440\u043e\u0437\u0456\u0440\u0432\u0430\u0442\u0438 \u0432\u0441\u0456 \u043f\u0440\u0438\u0437\u043d\u0430\u0447\u0435\u043d\u0456 \u0432\u0430\u043c \u0440\u043e\u0431\u043e\u0442\u0438, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gCZ(){return"\u0423\u0440\u0435\u0433\u0443\u043b\u044e\u0439\u0442\u0435 \u0432\u0441\u0456 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0456 \u0441\u043f\u043e\u0440\u0438, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gCU(){return"\u041f\u043e\u0433\u0430\u0441\u0456\u0442\u044c \u0437\u0430\u0431\u043e\u0440\u0433\u043e\u0432\u0430\u043d\u0456\u0441\u0442\u044c, \u043f\u0435\u0440\u0448 \u043d\u0456\u0436 \u0432\u0438\u0434\u0430\u043b\u044f\u0442\u0438 \u043e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441."},
gCT(){return"\u041e\u0431\u043b\u0456\u043a\u043e\u0432\u0438\u0439 \u0437\u0430\u043f\u0438\u0441 \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0432\u0438\u0434\u0430\u043b\u0438\u0442\u0438, \u0434\u043e\u043a\u0438 \u0454 \u0430\u043a\u0442\u0438\u0432\u043d\u0435 \u0437\u043e\u0431\u043e\u0432\u2019\u044f\u0437\u0430\u043d\u043d\u044f. \u0423\u0440\u0435\u0433\u0443\u043b\u044e\u0439\u0442\u0435 \u0439\u043e\u0433\u043e \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
