gO_(){return"\u0417\u0430\u043f\u0438\u0442 \u0441\u043a\u0430\u0441\u043e\u0432\u0430\u043d\u043e."},
gNZ(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438 \u0437\u0430\u043f\u0438\u0442. \u0421\u043f\u0440\u043e\u0431\u0443\u0439\u0442\u0435 \u0449\u0435 \u0440\u0430\u0437."},
