gIb(){return"\u0426\u0435 \u0430\u043d\u0443\u043b\u044e\u0454 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u043e\u0432\u0430\u043d\u0443 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044c. \u0412\u0430\u0448\u0443 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u044e \u0431\u0443\u0434\u0435 \u0432\u0456\u0434\u043a\u043b\u0438\u043a\u0430\u043d\u043e, \u0437\u0430\u043c\u043e\u0432\u043d\u0438\u043a \u043e\u0442\u0440\u0438\u043c\u0430\u0454 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f, \u0430 \u0434\u0456\u044e \u043d\u0435 \u043c\u043e\u0436\u043d\u0430 \u0431\u0443\u0434\u0435 \u0441\u043a\u0430\u0441\u0443\u0432\u0430\u0442\u0438."},
gIa(){return"\u0410\u043d\u0443\u043b\u044e\u0432\u0430\u0442\u0438 \u0439 \u0432\u0456\u0434\u043a\u043b\u0438\u043a\u0430\u0442\u0438"},
gId(){return"\u041d\u0435 \u0432\u0434\u0430\u043b\u043e\u0441\u044f \u0437\u0430\u0432\u0430\u043d\u0442\u0430\u0436\u0438\u0442\u0438 \u0443\u043c\u043e\u0432\u0438 \u043f\u0440\u043e\u043f\u043e\u0437\u0438\u0446\u0456\u0457. \u041f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0437\u2019\u0454\u0434\u043d\u0430\u043d\u043d\u044f \u0442\u0430 \u043f\u043e\u0432\u0442\u043e\u0440\u0456\u0442\u044c \u0441\u043f\u0440\u043e\u0431\u0443."},
