gHN(){return"\u0412\u0438\u043a\u043e\u043d\u0430\u0432\u0435\u0446\u044c \u0443\u0437\u044f\u0432 \u0437\u0430\u043c\u043e\u0432\u043b\u0435\u043d\u043d\u044f \u0432 \u0440\u043e\u0431\u043e\u0442\u0443"},
